const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:4173/');
  await page.waitForFunction(() => window.__bonk && document.fonts.status === 'loaded');
  await page.locator('#btnPlay').click();
  await page.waitForFunction(() => window.__bonk.state() === 'countdown');
  await page.evaluate(() => window.__bonk.play());
  await page.waitForFunction(() => window.__bonk.state() === 'play');
  const screenshot = '/tmp/opencode/dodgeball-latest.jpg';
  await page.screenshot({ path: screenshot, type: 'jpeg', quality: 70 });
  console.log(JSON.stringify({ pageErrors: errors, screenshot }));
  await browser.close();
  if (errors.length) process.exitCode = 1;
})().catch(e => { console.error(e); process.exitCode = 1; });
